-- MySMS PostgreSQL schema. Generated from the MySMS schema specification; do not edit by hand.

-- Module: time_attendance — Time & Attendance (hrms)

CREATE SCHEMA IF NOT EXISTS time_attendance;
COMMENT ON SCHEMA time_attendance IS 'Time & Attendance: daily staff attendance (manual entry, biometric/device capture, bulk import), an area of the hrms module beside hr and payroll. Holidays come from org.';

-- === P1-01: staff attendance (moved whole from attendance.staff_attendance, reorganisation 2c) ===

CREATE TABLE time_attendance.staff_attendance (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    staff_id uuid NOT NULL,
    attendance_date date NOT NULL,
    status varchar(20) NOT NULL,
    check_in_at timestamptz,
    check_out_at timestamptz,
    source varchar(20) NOT NULL DEFAULT 'manual',
    leave_application_id uuid,
    replaced_status varchar(20),
    recorded_by_user_id uuid,
    remark varchar(300),
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_staff_attendance PRIMARY KEY (id, attendance_date),
    CONSTRAINT ck_staff_attendance_status CHECK (status IN ('present', 'absent', 'half_day', 'late', 'on_leave', 'holiday')),
    CONSTRAINT ck_staff_attendance_source CHECK (source IN ('manual', 'biometric', 'import')),
    CONSTRAINT ck_staff_attendance_replaced_status CHECK (replaced_status IN ('present', 'absent', 'half_day', 'late', 'on_leave', 'holiday')),
    CONSTRAINT ck_staff_attendance_replaced_by_leave CHECK (replaced_status IS NULL OR leave_application_id IS NOT NULL)
) PARTITION BY RANGE (attendance_date);
CREATE TABLE time_attendance.staff_attendance_default PARTITION OF time_attendance.staff_attendance DEFAULT;
COMMENT ON TABLE time_attendance.staff_attendance IS 'Daily attendance of staff (manual, biometric import or bulk import). Partitioned monthly by attendance_date.';
COMMENT ON TABLE time_attendance.staff_attendance_default IS 'Default partition of time_attendance.staff_attendance. Monthly partitions are created ahead of time by the application maintenance job, so this partition should stay empty.';
COMMENT ON COLUMN time_attendance.staff_attendance.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN time_attendance.staff_attendance.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN time_attendance.staff_attendance.staff_id IS 'Staff member the day belongs to (hr.staff, the sibling area; plain reference, validated by the application).';
COMMENT ON COLUMN time_attendance.staff_attendance.attendance_date IS 'Attendance day (partition key).';
COMMENT ON COLUMN time_attendance.staff_attendance.status IS 'present / absent / half_day / late / on_leave / holiday.';
COMMENT ON COLUMN time_attendance.staff_attendance.check_in_at IS 'Clock-in time when captured.';
COMMENT ON COLUMN time_attendance.staff_attendance.check_out_at IS 'Clock-out time when captured.';
COMMENT ON COLUMN time_attendance.staff_attendance.source IS 'How the row was captured: manual, biometric or import.';
COMMENT ON COLUMN time_attendance.staff_attendance.leave_application_id IS 'Approved leave application that explains an on_leave (full day) or half_day (half-day leave) day (hr.leave_application, the sibling area: an in-module foreign key; set by the leave workflow only, LeaveAttendanceSync: one row per working day of the leave with the remark ''Leave: <leave type>'', removed again when the leave is cancelled unless someone has changed it since, in which case it stays as left, without the link).';
COMMENT ON COLUMN time_attendance.staff_attendance.replaced_status IS 'The status a day already recorded had before approved leave overrode it (leave wins): restored when the leave is cancelled. NULL = the row was written for the leave, and is removed when the leave is cancelled. Not on the contract.';
COMMENT ON COLUMN time_attendance.staff_attendance.recorded_by_user_id IS 'User who recorded or corrected the day.';
COMMENT ON COLUMN time_attendance.staff_attendance.remark IS 'Free-text remark.';
COMMENT ON COLUMN time_attendance.staff_attendance.created_at IS 'Row creation time.';
COMMENT ON COLUMN time_attendance.staff_attendance.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN time_attendance.staff_attendance.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN time_attendance.staff_attendance.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN time_attendance.staff_attendance.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN time_attendance.staff_attendance.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

-- In-module foreign key into the sibling hr schema (owner decision 2c: hr, payroll and time_attendance are one
-- module, so the leave link is a real, tenant-composite foreign key; hr.leave_application rows are only ever
-- soft-deleted, so the cleanup of the link stays event-driven on hr.leave_application.deleted).
ALTER TABLE time_attendance.staff_attendance ADD CONSTRAINT fk_staff_attendance_leave_application_id
    FOREIGN KEY (leave_application_id, tenant_id) REFERENCES hr.leave_application (id, tenant_id) ON DELETE RESTRICT;

-- === Review fixes: day-row uniqueness ignores soft-deleted rows ===

CREATE UNIQUE INDEX uq_staff_attendance_1 ON time_attendance.staff_attendance (staff_id, attendance_date) WHERE deleted_at IS NULL;

