-- === P1-13: transactional outbox / inbox ===

CREATE TABLE time_attendance.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    publish_error text,
    CONSTRAINT pk_time_attendance_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE time_attendance.outbox_event IS 'Transactional outbox of the time_attendance area: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN time_attendance.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN time_attendance.outbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN time_attendance.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN time_attendance.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN time_attendance.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN time_attendance.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN time_attendance.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN time_attendance.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
COMMENT ON COLUMN time_attendance.outbox_event.publish_error IS 'Why the relay could not turn the row into an event (set aside, not published); NULL otherwise.';
CREATE INDEX ix_time_attendance_outbox_event_pending ON time_attendance.outbox_event (id) WHERE published_at IS NULL AND publish_error IS NULL;
CREATE TABLE time_attendance.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_time_attendance_inbox_event PRIMARY KEY (tenant_id, event_id)
);
COMMENT ON TABLE time_attendance.inbox_event IS 'Inbox of the time_attendance area: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN time_attendance.inbox_event.event_id IS 'Global id of the consumed event; recorded per tenant.';
COMMENT ON COLUMN time_attendance.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN time_attendance.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN time_attendance.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN time_attendance.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN time_attendance.inbox_event.processing_error IS 'Last handling error, if any.';
CREATE INDEX ix_time_attendance_inbox_event_processed ON time_attendance.inbox_event (processed_at) WHERE processed_at IS NOT NULL;

-- === Module-local infrastructure (distributed deployment: no cross-module access) ===
CREATE TABLE time_attendance.idempotency_key (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    user_id uuid,
    operation_name varchar(120) NOT NULL,
    request_hash varchar(64),
    response_status smallint,
    response_body text,
    locked_at timestamptz,
    completed_at timestamptz,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_time_attendance_idempotency_key PRIMARY KEY (id),
    CONSTRAINT uq_time_attendance_idempotency_key_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE time_attendance.idempotency_key IS 'Module-local idempotency store of the time_attendance area: stored outcome of a write carrying an Idempotency-Key; replays return the stored response. Rows expire after 24h (cleanup job).';
