COMMENT ON COLUMN time_attendance.idempotency_key.response_body IS 'Stored response body.';
COMMENT ON COLUMN time_attendance.idempotency_key.locked_at IS 'Set while the first attempt is still executing.';
COMMENT ON COLUMN time_attendance.idempotency_key.completed_at IS 'When the stored response was written.';
COMMENT ON COLUMN time_attendance.idempotency_key.expires_at IS 'When the row may be purged.';
