COMMENT ON COLUMN time_attendance.idempotency_key.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN time_attendance.idempotency_key.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN time_attendance.idempotency_key.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
