-- === Privacy tasks (design PRIVACY-AND-CONSENT-CENTRE §9.1, §10) and the area's scheduled jobs (core JobSchedule) ===
CREATE TABLE time_attendance.privacy_task_receipt (
    task_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    kind varchar(10) NOT NULL,
    payload jsonb NOT NULL,
    status varchar(15) NOT NULL DEFAULT 'received',
    result jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    CONSTRAINT pk_time_attendance_privacy_task_receipt PRIMARY KEY (task_id),
    CONSTRAINT ck_time_attendance_privacy_task_receipt_kind CHECK (kind IN ('task', 'retention')),
    CONSTRAINT ck_time_attendance_privacy_task_receipt_status CHECK (status IN ('received', 'done', 'partial', 'failed',
        'not_applicable')),
    CONSTRAINT ck_time_attendance_privacy_task_receipt_completed CHECK ((status = 'received') = (completed_at IS NULL))
);
COMMENT ON TABLE time_attendance.privacy_task_receipt IS 'The privacy tasks and retention runs privacy sent this area (privacy.rights_request.task_assigned, privacy.retention.due), one row per task or run id: a task dispatched again runs once, is retried after a failure and is answered again from the stored answer (privacy-client PrivacyTaskHandler). Ids, codes and counts only.';
COMMENT ON COLUMN time_attendance.privacy_task_receipt.task_id IS 'The rights-request task id or the retention run id privacy sent; the id the module answers with.';
COMMENT ON COLUMN time_attendance.privacy_task_receipt.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN time_attendance.privacy_task_receipt.kind IS 'task (a rights-request task) or retention (a retention run).';
COMMENT ON COLUMN time_attendance.privacy_task_receipt.payload IS 'The event''s data as privacy sent it: ids, codes and dates only.';
COMMENT ON COLUMN time_attendance.privacy_task_receipt.status IS 'received (waiting for the module''s job), done, partial, failed or not_applicable.';
COMMENT ON COLUMN time_attendance.privacy_task_receipt.result IS 'The answer published (<module>.privacy_task.completed or <module>.privacy_retention.completed): counts and codes; null while received.';
COMMENT ON COLUMN time_attendance.privacy_task_receipt.created_at IS 'When the task or run first arrived.';
COMMENT ON COLUMN time_attendance.privacy_task_receipt.completed_at IS 'When the module answered; null while received.';
CREATE INDEX ix_time_attendance_privacy_task_receipt_received ON time_attendance.privacy_task_receipt (tenant_id, created_at) WHERE status = 'received';
COMMENT ON INDEX time_attendance.ix_time_attendance_privacy_task_receipt_received IS 'The tasks and runs waiting for the module''s job, the oldest first.';
CREATE TABLE time_attendance.job_schedule (
    job_code varchar(60) NOT NULL,
    tenant_id uuid NOT NULL,
    next_run_at timestamptz NOT NULL,
    lease_owner uuid,
    lease_until timestamptz,
    last_run_at timestamptz,
    failures integer NOT NULL DEFAULT 0,
    last_error varchar(500),
    CONSTRAINT pk_job_schedule PRIMARY KEY (job_code, tenant_id),
    CONSTRAINT ck_job_schedule_lease CHECK ((lease_owner IS NULL) = (lease_until IS NULL)),
    CONSTRAINT ck_job_schedule_failures CHECK (failures >= 0)
);
COMMENT ON TABLE time_attendance.job_schedule IS 'When each tenant is next due for each scheduled job of the area (core JobSchedule, ROADMAP ARC-4). A tenant is enrolled the first time it has work for the job. Job codes, tenant ids and times only, no personal data, and no row-level security: the job runner claims due rows across tenants, then runs each in its tenant''s own context.';
COMMENT ON COLUMN time_attendance.job_schedule.job_code IS 'The job (<module>.<name>): time_attendance.privacy_tasks (runs the privacy tasks and retention runs of time_attendance.privacy_task_receipt).';
COMMENT ON COLUMN time_attendance.job_schedule.tenant_id IS 'The tenant the job runs for.';
COMMENT ON COLUMN time_attendance.job_schedule.next_run_at IS 'When the tenant is next due.';
COMMENT ON COLUMN time_attendance.job_schedule.lease_owner IS 'The runner (a random id per process) holding the tenant''s run; null while no run is held.';
COMMENT ON COLUMN time_attendance.job_schedule.lease_until IS 'Until when the lease holds; after it another runner may take the run over.';
COMMENT ON COLUMN time_attendance.job_schedule.last_run_at IS 'When the last run ended, finished or failed.';
COMMENT ON COLUMN time_attendance.job_schedule.failures IS 'Failed runs in a row; the retry delay doubles with each.';
COMMENT ON COLUMN time_attendance.job_schedule.last_error IS 'Why the last run failed (exception class and message, first 500 characters); null after a finished run.';
CREATE INDEX ix_job_schedule_due ON time_attendance.job_schedule (next_run_at);
COMMENT ON INDEX time_attendance.ix_job_schedule_due IS 'The due runs, the longest overdue first.';

-- === P0-03: row-level security (tenant isolation). The application role is not the table owner and sets app.tenant_id per transaction; a platform-admin role with BYPASSRLS serves cross-tenant operations ===

ALTER TABLE time_attendance.staff_attendance ENABLE ROW LEVEL SECURITY;
ALTER TABLE time_attendance.staff_attendance FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON time_attendance.staff_attendance USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE time_attendance.outbox_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE time_attendance.outbox_event FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON time_attendance.outbox_event USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE time_attendance.inbox_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE time_attendance.inbox_event FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON time_attendance.inbox_event USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE time_attendance.idempotency_key ENABLE ROW LEVEL SECURITY;
ALTER TABLE time_attendance.idempotency_key FORCE ROW LEVEL SECURITY;
